// Normalizar y validar datos de entrada
const actions = $json.actions || [];
const sessionData = $json.sessionData || {};

// Validar estructura de acciones
const validActions = actions.filter(action => {
  return action.type && action.selector && action.timestamp;
});

// Enriquecer datos con metadata
const enrichedData = {
  sessionId: sessionData.sessionId || `session_${Date.now()}`,
  totalActions: validActions.length,
  captureTime: new Date().toISOString(),
  sourceUrl: sessionData.url || '',
  pageTitle: sessionData.title || '',
  userAgent: $json.userAgent || '',
  actions: validActions.map((action, index) => ({
    ...action,
    actionIndex: index + 1,
    relativeTime: action.timestamp - validActions[0].timestamp
  }))
};

return [{json: enrichedData}];

