// Procesar respuesta de Gemini para Playwright
const response = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';

// Limpiar y formatear código
const cleanCode = response
  .replace(/```typescript/gi, '')
  .replace(/```javascript/gi, '')
  .replace(/```/g, '')
  .trim();

// Validar que contiene código Playwright
const isValidPlaywright = cleanCode.includes('page.') && 
                         (cleanCode.includes('test(') || cleanCode.includes('test.describe'));

if (!isValidPlaywright) {
  throw new Error('Generated code is not valid Playwright test');
}

return [{
  json: {
    testType: 'playwright',
    generatedCode: cleanCode,
    filename: `playwright-test-${Date.now()}.spec.ts`,
    sessionId: $('Data Validation & Enrichment').item.json.sessionId,
    generatedAt: new Date().toISOString(),
    codeLength: cleanCode.length,
    linesCount: cleanCode.split('\n').length
  }
}];

// Procesar respuesta de Gemini para CSV
const response = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';

// Limpiar CSV
const cleanCsv = response
  .replace(/```csv/gi, '')
  .replace(/```/g, '')
  .trim();

// Validar formato CSV
const lines = cleanCsv.split('\n').filter(line => line.trim());
const hasHeader = lines[0] && lines[0].includes('Step') && lines[0].includes('Action');

if (!hasHeader || lines.length < 2) {
  throw new Error('Generated CSV is not valid');
}

return [{
  json: {
    testType: 'manual',
    generatedCsv: cleanCsv,
    filename: `manual-test-${Date.now()}.csv`,
    sessionId: $('Data Validation & Enrichment').item.json.sessionId,
    generatedAt: new Date().toISOString(),
    stepsCount: lines.length - 1,
    csvSize: cleanCsv.length
  }
}];

// Crear estructura final de datos
const playwrightData = $input.first()?.json || {};
const csvData = $input.last()?.json || {};
const originalData = $('Data Validation & Enrichment').item.json;

// Estadísticas de análisis
const analysis = {
  actionTypes: {},
  selectorTypes: {},
  avgTimeBetweenActions: 0
};

// Analizar tipos de acciones
originalData.actions.forEach(action => {
  analysis.actionTypes[action.type] = (analysis.actionTypes[action.type] || 0) + 1;

  // Analizar tipos de selectores
  if (action.selector.startsWith('#')) {
    analysis.selectorTypes.id = (analysis.selectorTypes.id || 0) + 1;
  } else if (action.selector.startsWith('.')) {
    analysis.selectorTypes.class = (analysis.selectorTypes.class || 0) + 1;
  } else if (action.selector.includes(':nth-child')) {
    analysis.selectorTypes.nthChild = (analysis.selectorTypes.nthChild || 0) + 1;
  } else {
    analysis.selectorTypes.other = (analysis.selectorTypes.other || 0) + 1;
  }
});

// Calcular tiempo promedio entre acciones
if (originalData.actions.length > 1) {
  const totalTime = originalData.actions[originalData.actions.length - 1].relativeTime;
  analysis.avgTimeBetweenActions = Math.round(totalTime / (originalData.actions.length - 1));
}

const finalResult = {
  sessionId: originalData.sessionId,
  processedAt: new Date().toISOString(),
  source: {
    url: originalData.sourceUrl,
    title: originalData.pageTitle,
    captureTime: originalData.captureTime
  },
  analysis,
  tests: {
    playwright: {
      code: playwrightData.generatedCode || '',
      filename: playwrightData.filename || '',
      linesCount: playwrightData.linesCount || 0
    },
    manual: {
      csv: csvData.generatedCsv || '',
      filename: csvData.filename || '',
      stepsCount: csvData.stepsCount || 0
    }
  },
  rawActions: originalData.actions,
  metrics: {
    totalActions: originalData.totalActions,
    playwrightCodeLength: playwrightData.codeLength || 0,
    csvSize: csvData.csvSize || 0,
    processingTime: Date.now() - new Date(originalData.captureTime).getTime()
  }
};

return [{json: finalResult}];

// Log final workflow completion
console.log('✅ TestBuilder workflow completed successfully');
console.log('Session ID:', $json.sessionId);
console.log('Tests generated:', Object.keys($json.tests));

// Prepare response for webhook
const response = {
  success: true,
  sessionId: $json.sessionId,
  message: 'Tests generated and processed successfully',
  timestamp: new Date().toISOString(),
  summary: {
    actionsProcessed: $json.metrics.totalActions,
    playwrightGenerated: !!$json.tests.playwright.code,
    csvGenerated: !!$json.tests.manual.csv,
    processingTimeMs: $json.metrics.processingTime
  },
  tests: {
    playwright: {
      filename: $json.tests.playwright.filename,
      linesCount: $json.tests.playwright.linesCount,
      code: $json.tests.playwright.code
    },
    manual: {
      filename: $json.tests.manual.filename,
      stepsCount: $json.tests.manual.stepsCount,
      csv: $json.tests.manual.csv
    }
  },
  analysis: $json.analysis
};

return [{json: response}];

// Error handler para casos con pocas acciones
const errorResponse = {
  success: false,
  error: 'Insufficient actions for test generation',
  message: 'At least 3 actions are required to generate meaningful tests',
  actionsReceived: $json.totalActions || 0,
  minimumRequired: 3,
  suggestions: [
    'Perform more interactions with the page',
    'Ensure the TestBuilder extension is recording properly',
    'Try recording a complete user workflow'
  ]
};

return [{json: errorResponse}];
